require __DIR__ . '/../../app/admin/bootstrap.php';$search=mb_substr(trim($_GET['search']??''),0,100);$total=(int)db_run('SELECT COUNT(*) total FROM products WHERE name LIKE ?',['%'.$search.'%'])->get_result()->fetch_assoc()['total'];$pages=max(1,(int)ceil($total/15));$page=max(1,min($pages,(int)($_GET['page']??1)));
$rows=db_run('SELECT * FROM products WHERE name LIKE ? ORDER BY id DESC LIMIT 15 OFFSET ?',['%'.$search.'%',($page-1)*15])->get_result()->fetch_all(MYSQLI_ASSOC);
admin_open('Quản lý sản phẩm','Thêm ảnh, đánh dấu hàng mới/nổi bật hoặc ẩn sản phẩm khỏi cửa hàng.');
