<div class="d-flex justify-content-between flex-wrap gap-3 mb-4"><form method="get" class="d-flex gap-2"><label for="search" class="visually-hidden">Tìm sản phẩm</label><input class="form-control" id="search" name="search" placeholder="Tên sản phẩm" value="<?= e($search) ?>"><button class="btn btn-outline-dark">Tìm</button></form><a class="btn btn-dark" href="add_product.php">Thêm sản phẩm</a></div>
